  const ctl = txs.filter(tx => tx > 0).map(tx => { const a = TVA_COLL[tx]; const B0 = (base[tx] || 0) + P2n((adj[tx] || {}).faeN1) - P2n((adj[tx] || {}).faeN) + P2n((adj[tx] || {}).pcaN) - P2n((adj[tx] || {}).pcaN1); const th = Math.round(B0 * tx / 10000); let an = 0, cr = 0, db = 0, liq = 0; if (a) for (const { e, l } of flat({ from: ex.debut, to: ex.fin })) { if (!l.compte.startsWith(a)) continue; if (e.journal === "AN") an += l.credit - l.debit; else if (e.tag === "TVA") liq += l.debit - l.credit; else { cr += l.credit; db += l.debit; } } const cpt = cr - db; return { tx, base: base[tx] || 0, B0, th, an, cr, db, cpt, dec: decl[tx] || 0, liq, fin: an + cpt - liq, ecD: th - (decl[tx] || 0), ecC: th - cpt }; });
