const P3_DEV = ["USD", "GBP", "CHF", "JPY", "CNY", "CAD", "AUD", "SEK", "NOK", "DKK", "PLN", "CZK", "HUF", "TRY", "MAD", "TND", "XOF", "AED", "SGD", "HKD", "INR", "BRL", "MXN"];
